update t_capp_ai_memory_extract_job set status='PENDING',last_error_type=#{errorType},
    lease_until=null,next_attempt_at=date_add(current_timestamp(3),interval #{delaySeconds} second),updated_at=current_timestamp(3)
where run_id=#{runId}

